import { mergeVariantReferences } from '../../types/variant-reference';
import { z } from 'zod';
import fs from 'fs/promises';
import { createHash, randomUUID } from 'crypto';
import { findHub } from '../../library/HubClient';
import { currentLibraryRoot } from '../ProjectLibrary';
import { getConfigManager } from '../ConfigManager';
import { bindProfileAccount } from './profileAccount';
import { guidanceAttachments } from '../guidanceDelivery';
import { ProfileContextConflict } from '../../storage/profiles/contextReceipts';
import {
  ProfileRuntimeSchema,
  ProfilePacketSchema,
  ProfileContextSchema,
  type ProfilePacket,
  type ProfileContextResult,
  type PickTrigger,
} from '../../types/design-profile';
import type {
  ChangeRequest,
  CommentChangeItem,
} from '../../types/change-request-types';
import type { RawUserContextInput } from '../../agent-variants/contracts';

const PREPARATION_REQUEST_TIMEOUT_MS = 51_000;
const CONTEXT_RECORD_TIMEOUT_MS = 2_000;
const MAX_CONTEXT_IMAGE_BYTES = 35 * 1024 * 1024;
const CONFLICT_STATUS = 409;
const profileImageHashes = new WeakMap<ProfileContextResult, Set<string>>();

export const attachProfilePacket = async (
  request: ChangeRequest,
  packet: ProfilePacket & { profileId?: string },
): Promise<ChangeRequest> => {
  const changes = await Promise.all(
    request.changes.map(async (change) => {
      if (change.kind !== 'comment' || !change.variantRequest) return change;
      const trace = {
        ...ProfileContextSchema.parse(packet),
        profileId: packet.profileId,
        isRecorded: false,
      };
      if (change.variantRequest.profile === 'off')
        return {
          ...change,
          profileContext: undefined,
          profileTrace: {
            ...trace,
            status: 'off' as const,
            selected: [],
            images: [],
            suppliedReferences: undefined,
            failedUploadCount: undefined,
          },
        };
      if (change.variantRequest.profile !== 'auto') {
        let status: ProfilePacket['status'] = 'off';
        if (change.images?.length && trace.status !== 'off') {
          if (trace.status === 'selected')
            status =
              trace.suppliedReferences?.length || trace.failedUploadCount
                ? 'empty'
                : 'off';
          else status = trace.status;
        }
        return {
          ...change,
          profileContext: undefined,
          profileTrace: {
            ...trace,
            status,
            selected: [],
            images: [],
          },
        };
      }
      if (packet.status !== 'selected')
        return { ...change, profileContext: undefined, profileTrace: trace };
      const explicit = change.images ?? [];
      const bytes = explicit.map((dataUrl) =>
        Buffer.from(dataUrl.slice(dataUrl.indexOf(',') + 1), 'base64'),
      );
      const hashes = new Set(
        bytes.map((image) => createHash('sha256').update(image).digest('hex')),
      );
      let size = bytes.reduce((sum, image) => sum + image.length, 0);
      for (const image of guidanceAttachments(request.guidance ?? [])) {
        if (!hashes.has(image.hash)) size += image.bytes;
        hashes.add(image.hash);
      }
      const images = [...explicit];
      const addedImageHashes = new Set<string>();
      const delivered: ProfilePacket['images'] = [];
      for (const image of packet.images) {
        if (hashes.has(image.hash)) {
          delivered.push(image);
          continue;
        }
        const stat = await fs.lstat(image.path);
        if (!stat.isFile() || size + stat.size > MAX_CONTEXT_IMAGE_BYTES)
          continue;
        const body = await fs.readFile(image.path);
        if (createHash('sha256').update(body).digest('hex') !== image.hash)
          throw new Error('Profile context image failed integrity validation');
        delivered.push(image);
        images.push(`data:${image.mimeType};base64,${body.toString('base64')}`);
        addedImageHashes.add(image.hash);
        size += body.length;
        hashes.add(image.hash);
      }
      const profileTrace = { ...trace, images: delivered };
      profileImageHashes.set(profileTrace, addedImageHashes);
      return {
        ...change,
        images,
        profileContext: packet.contextText,
        profileTrace,
      };
    }),
  );
  return { ...request, changes };
};

const withPicksAsAutomatic = (request: ChangeRequest): ChangeRequest => ({
  ...request,
  changes: request.changes.map((change) =>
    change.kind === 'comment' &&
    change.variantRequest?.referencePicks &&
    change.variantRequest.profile !== 'off'
      ? {
          ...change,
          variantRequest: { ...change.variantRequest, profile: 'auto' },
        }
      : change,
  ),
});

export const prepareProfileRequest = async (
  submitted: ChangeRequest,
): Promise<ChangeRequest> => {
  const request = withPicksAsAutomatic(submitted);
  const comments = request.changes.filter(
    (change): change is CommentChangeItem =>
      change.kind === 'comment' && Boolean(change.variantRequest),
  );
  const comment =
    comments.find(
      (change) =>
        change.variantRequest?.referencePicks &&
        change.variantRequest.profile === 'auto',
    ) ??
    comments.find((change) => change.variantRequest?.profile === 'auto') ??
    comments.find((change) => change.variantRequest?.profile !== 'off') ??
    comments[0];
  if (!comment) return request;
  const uploads = comments.flatMap((change) =>
    change.variantRequest?.profile === 'off' ? [] : (change.images ?? []),
  );
  const requestId = request.agentRunId ?? request.traceId ?? randomUUID();
  const referencePicks =
    comment.variantRequest?.profile === 'auto'
      ? comment.variantRequest.referencePicks
      : undefined;
  const pickTrigger: PickTrigger = submitted.changes.some(
    (change) =>
      change.kind === 'comment' &&
      change.variantRequest?.referencePicks &&
      change.variantRequest.profile === 'auto',
  )
    ? 'user_requested'
    : 'autonomous';
  const mode =
    comment.variantRequest?.profile ?? (uploads.length ? 'uploads' : 'off');
  const fallback: ProfilePacket = {
    requestId,
    status: mode === 'off' ? 'off' : 'unavailable',
    queries: [],
    candidateIds: [],
    selected: [],
    contextText: '',
    images: [],
    durationMs: 0,
  };
  const config = getConfigManager();
  const accountId = config.getUserId();
  const selected =
    process.env.RIVET_EXECUTOR_VENDOR ??
    request.workerSelection?.provider ??
    config.getConfiguredWorkerVendor() ??
    (request.initiator?.kind === 'agent'
      ? request.initiator.agent
      : undefined) ??
    config.getConfiguredRunner();
  const runtime = ProfileRuntimeSchema.safeParse(selected);
  if (!runtime.success || !config.isAuthenticated() || !accountId)
    return attachProfilePacket(request, fallback);
  try {
    const hub = await findHub(currentLibraryRoot());
    if (!hub) return attachProfilePacket(request, fallback);
    const excludedMediaHashes = uploads.map((image) =>
      createHash('sha256')
        .update(Buffer.from(image.slice(image.indexOf(',') + 1), 'base64'))
        .digest('hex'),
    );
    excludedMediaHashes.push(
      ...guidanceAttachments(request.guidance ?? []).map((image) => image.hash),
    );
    const response = await fetch(
      `${hub.url}/api/library/profile/preparations`,
      {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${hub.token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          accountId,
          requestId,
          mode,
          instruction: [
            comment.instruction,
            ...(comment.variantRequest?.briefs ?? []).map(
              (brief) => `${brief.label}: ${brief.body}`,
            ),
          ].join('\n'),
          runtime: runtime.data,
          excludedMediaHashes,
          ...(uploads.length ? { uploads } : {}),
          ...(referencePicks ? { referencePicks, pickTrigger } : {}),
        }),
        signal: AbortSignal.timeout(
          mode === 'off'
            ? CONTEXT_RECORD_TIMEOUT_MS
            : PREPARATION_REQUEST_TIMEOUT_MS,
        ),
      },
    );
    if (referencePicks && response.status === CONFLICT_STATUS)
      throw new ProfileContextConflict(
        z.object({ error: z.string() }).parse(await response.json()).error,
      );
    if (!response.ok) return attachProfilePacket(request, fallback);
    const packet = ProfilePacketSchema.extend({
      profileId: z.string().min(1),
      accountId: z.string().min(1),
    }).parse(await response.json());
    if (packet.accountId !== accountId)
      return attachProfilePacket(request, fallback);
    const prepared = await attachProfilePacket(request, packet);
    if (!config.isAuthenticated() || config.getUserId() !== accountId)
      return attachProfilePacket(request, fallback);
    bindProfileAccount(prepared, accountId);
    return prepared;
  } catch (error) {
    if (error instanceof ProfileContextConflict) throw error;
    return attachProfilePacket(request, fallback);
  }
};

export const recordProfileRequest = async (
  request: ChangeRequest,
): Promise<ProfileContextResult | undefined> => {
  const comments = request.changes.filter(
    (change): change is CommentChangeItem =>
      change.kind === 'comment' && Boolean(change.profileTrace),
  );
  const comment =
    comments.find(
      (change) =>
        change.variantRequest?.profile === 'auto' &&
        change.profileTrace?.status !== 'off',
    ) ??
    comments.find((change) => change.profileTrace?.status !== 'off') ??
    comments[0];
  const trace = comment?.profileTrace;
  if (!trace) return undefined;
  const context = ProfileContextSchema.parse(trace);
  const result = { ...context, isRecorded: false };
  if (!trace.profileId) return result;
  try {
    const hub = await findHub(currentLibraryRoot());
    if (!hub) return result;
    const response = await fetch(
      `${hub.url}/api/library/profile/contexts/${encodeURIComponent(context.requestId)}`,
      {
        method: 'PUT',
        headers: {
          Authorization: `Bearer ${hub.token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ profileId: trace.profileId, context }),
        signal: AbortSignal.timeout(CONTEXT_RECORD_TIMEOUT_MS),
      },
    );
    return { ...context, isRecorded: response.ok };
  } catch {
    return result;
  }
};

export const profileReferences = (
  comment: CommentChangeItem,
  dataUrl?: string,
) => {
  if (!comment.profileTrace) return undefined;
  const hash = dataUrl
    ? createHash('sha256')
        .update(Buffer.from(dataUrl.slice(dataUrl.indexOf(',') + 1), 'base64'))
        .digest('hex')
    : undefined;
  return mergeVariantReferences(
    hash
      ? comment.profileTrace.suppliedReferences?.filter(
          (reference) => reference.image?.hash === hash,
        )
      : undefined,
    (comment.profileTrace.status === 'selected'
      ? comment.profileTrace.selected
      : []
    )
      .filter((selection) => !hash || selection.mediaHashes?.includes(hash))
      .map((selection) => {
        const delivered = hash
          ? comment.profileTrace?.images.find((image) => image.hash === hash)
          : undefined;
        return {
          ...selection,
          ...(delivered
            ? { image: { hash: delivered.hash, mimeType: delivered.mimeType } }
            : {}),
        };
      }),
  );
};

export const profileContextInputs = (comment: CommentChangeItem) => {
  const userContextInputs: RawUserContextInput[] = [];
  const profileContextInputs: RawUserContextInput[] = [];
  const hashes = comment.profileTrace
    ? profileImageHashes.get(comment.profileTrace)
    : undefined;
  for (const [index, dataUrl] of (comment.images ?? []).entries()) {
    const hash = createHash('sha256')
      .update(Buffer.from(dataUrl.slice(dataUrl.indexOf(',') + 1), 'base64'))
      .digest('hex');
    const isProfileImage = hashes?.has(hash) ?? false;
    const imageInput = {
      transport: 'upload' as const,
      dataUrl,
      label: `Reference image ${index + 1}`,
      userIntent: 'Inline variant visual reference',
    };
    const selectedReferences = hashes
      ? profileReferences(comment, dataUrl)?.filter((reference) =>
          comment.profileTrace?.selected.some(
            (selection) => selection.id === reference.id,
          ),
        )
      : undefined;
    if (isProfileImage || selectedReferences?.length)
      profileContextInputs.push({
        ...imageInput,
        references: selectedReferences,
      });
    if (!isProfileImage)
      userContextInputs.push({
        ...imageInput,
        references: mergeVariantReferences(
          comment.profileTrace?.suppliedReferences?.filter(
            (reference) => reference.image?.hash === hash,
          ),
        ),
      });
  }
  if (comment.profileContext) {
    const inputs = hashes ? profileContextInputs : userContextInputs;
    inputs.push({
      transport: 'text',
      label: 'Design profile references',
      content: comment.profileContext,
      references: profileReferences(comment),
    });
  }
  return { userContextInputs, profileContextInputs };
};

export const profileReferenceMode = (
  comment: CommentChangeItem,
): 'inherit' | 'replace' =>
  comment.variantRequest?.profile !== undefined ||
  comment.variantRequest?.referencePicks
    ? 'replace'
    : 'inherit';
